# =====================================================================
# 🆕 IP Geolocation (random with cache for stability)
# =====================================================================
def get_ip_geolocation(ip):
    """Return (lat, lon, country) for an IP address.

    Uses a deterministic random map seeded by the IP — same IP always
    gets the same location (cached). This simulates geolocation without
    requiring external API calls.
    """
    if ip in st.session_state.ip_geo_cache:
        return st.session_state.ip_geo_cache[ip]

    # Distribute IPs across a curated list of cybersecurity-relevant countries
    countries = [
        ('Russia',       55.75, 37.61),
        ('China',        39.90, 116.40),
        ('USA',          37.77, -122.41),
        ('Brazil',       -23.55, -46.63),
        ('Iran',         35.68, 51.38),
        ('North Korea',  39.03, 125.75),
        ('India',        28.61, 77.20),
        ('Romania',      44.43, 26.10),
        ('Ukraine',      50.45, 30.52),
        ('Vietnam',      21.03, 105.85),
        ('Turkey',       41.00, 28.97),
        ('Germany',      52.52, 13.40),
        ('UK',           51.50, -0.12),
        ('Netherlands',  52.37, 4.89),
        ('Indonesia',    -6.21, 106.85),
        ('Mexico',       19.43, -99.13),
        ('Egypt',        30.04, 31.23),
        ('Nigeria',      9.08, 7.49),
        ('Saudi Arabia', 24.71, 46.67),
        ('Pakistan',     33.69, 73.05),
    ]

    # Seed RNG with IP digits → deterministic mapping
    seed = sum(int(p) * (i+1) for i, p in enumerate(ip.replace('.', '0').split('0')) if p.isdigit())
    rng = random.Random(seed)
    base = rng.choice(countries)
    # Add small jitter so multiple IPs from same country don't overlap exactly
    lat = base[1] + rng.uniform(-2, 2)
    lon = base[2] + rng.uniform(-2, 2)
    country = base[0]
    result = (lat, lon, country)
    st.session_state.ip_geo_cache[ip] = result
    return result


def render_geo_map(attacks):
    """🆕 Render a world map with attack origin markers (Plotly scattergeo)."""
    if not attacks:
        return None

    rows = []
    for a in attacks:
        ip = a.get('src_ip', '0.0.0.0')
        lat, lon, country = get_ip_geolocation(ip)
        rows.append({
            'ip': ip, 'lat': lat, 'lon': lon, 'country': country,
            'severity': a.get('severity', 'Medium'),
            'name': a.get('name', 'Attack'),
            'icon': a.get('icon', '⚡'),
            'time': a.get('timestamp', ''),
        })

    df = pd.DataFrame(rows)
    sev_color = {'Critical': '#ff4b2b', 'High': '#ffaa00', 'Medium': '#00d4ff'}
    sev_size = {'Critical': 22, 'High': 16, 'Medium': 12}

    fig = go.Figure()
    for sev in ['Medium', 'High', 'Critical']:  # critical on top
        sub = df[df.severity == sev]
        if sub.empty:
            continue
        fig.add_trace(go.Scattergeo(
            lon=sub.lon, lat=sub.lat,
            mode='markers',
            marker=dict(size=sev_size.get(sev, 12),
                        color=sev_color.get(sev, '#aaa'),
                        line=dict(color='white', width=1),
                        opacity=0.85),
            text=sub.apply(lambda r: f"{r['icon']} {r['name']}<br>"
                                       f"📍 {r['country']}<br>"
                                       f"🌐 {r['ip']}<br>"
                                       f"⚠️ {r['severity']}", axis=1),
            hovertemplate='%{text}<extra></extra>',
            name=sev))

    fig.update_geos(
        projection_type='natural earth',
        showland=True, landcolor='rgb(20, 30, 60)',
        showocean=True, oceancolor='rgb(8, 12, 30)',
        showcountries=True, countrycolor='rgba(80, 100, 140, 0.4)',
        showcoastlines=True, coastlinecolor='rgba(120, 140, 180, 0.3)',
        showframe=False,
        bgcolor='rgba(0,0,0,0)')

    fig.update_layout(
        title=dict(text='🌍 Global Attack Origins', x=0.5,
                   font=dict(color='#00d4ff', size=18)),
        paper_bgcolor='rgba(10,10,30,1)',
        font=dict(color='white'),
        height=500,
        margin=dict(l=0, r=0, t=40, b=0),
        legend=dict(bgcolor='rgba(15,15,40,0.7)',
                    bordercolor='rgba(0,212,255,0.3)', borderwidth=1))
    return fig


