def render_attack_heatmap(attacks, devices):
    """🔥 Render a heatmap showing which devices are most targeted."""
    if not attacks or not devices:
        return None

    # Count attacks per device
    device_ids = sorted({d['id'] for d in devices if d['type'] in ('server', 'router')})
    severities = ['Critical', 'High', 'Medium']

    matrix = np.zeros((len(severities), len(device_ids)))
    for a in attacks:
        tgt = a.get('target_id')
        sev = a.get('severity', 'Medium')
        if tgt in device_ids and sev in severities:
            matrix[severities.index(sev)][device_ids.index(tgt)] += 1

    fig = go.Figure(data=go.Heatmap(
        z=matrix,
        x=device_ids,
        y=severities,
        colorscale=[[0, 'rgba(10,10,30,1)'],
                    [0.3, 'rgba(0,212,255,0.4)'],
                    [0.6, 'rgba(255,170,0,0.7)'],
                    [1, 'rgba(255,75,43,1)']],
        text=matrix.astype(int),
        texttemplate='%{text}',
        textfont=dict(color='white', size=14),
        hovertemplate='Device: %{x}<br>Severity: %{y}<br>Attacks: %{z}<extra></extra>',
        colorbar=dict(title='Attacks', tickfont=dict(color='white'))))

    fig.update_layout(
        title=dict(text='🔥 Devices Under Attack — Heatmap',
                   x=0.5, font=dict(color='#ff4b2b', size=16)),
        paper_bgcolor='rgba(10,10,30,1)',
        plot_bgcolor='rgba(10,10,30,1)',
        font=dict(color='white'),
        height=350,
        xaxis=dict(title='Device ID', side='bottom'),
        yaxis=dict(title='Severity'),
        margin=dict(l=80, r=20, t=60, b=80))
    return fig


