def render_siem_log_entry(attack):
    """Render a single attack as a SIEM-style log line."""
    sev = attack.get('severity', 'Medium').lower()
    ts = attack.get('timestamp', '')
    name = attack.get('name', 'Unknown')
    src = attack.get('src_ip', '?')
    tgt = attack.get('target_id', '?')
    action = attack.get('action_taken', '⏳ Pending')
    icon = attack.get('icon', '⚡')

    sev_color = {'critical':'#ff4b2b', 'high':'#ffaa00', 'medium':'#00d4ff'}.get(sev, '#888')
    resolved_class = ' resolved' if attack.get('status') == 'Resolved' else ''

    return f"""
    <div class="siem-log {sev}{resolved_class}">
      <span class="siem-timestamp">{ts}</span>
      <span class="siem-tag" style="background:{sev_color}33; color:{sev_color};">
        {sev.upper()}
      </span>
      <span style="color:white;">{icon} <b>{name}</b></span>
      &nbsp;|&nbsp; src=<code style="color:#ffaa00;">{src}</code>
      &nbsp;|&nbsp; dst=<code style="color:#00d4ff;">{tgt}</code>
      <br/>
      <span style="color:#888; font-size:0.8em; margin-left:1rem;">
        ↳ action: {action}
      </span>
    </div>
    """


