# 🆕 PDF Report Generation (using reportlab)
# =====================================================================
def generate_pdf_report(attack_log, devices, accuracy, precision, recall, f1):
    """Generate a professional PDF report of the system's activity.

    Includes: cover page, statistics summary, attack log table, ML metrics,
    and recommendations. Returns bytes ready for download.

    🔑 IMPORTANT: This function uses reportlab's default Helvetica font,
    which does NOT support emoji glyphs or RTL Arabic text. Both must be
    stripped before being passed to Paragraph() — otherwise reportlab
    raises a silent exception and the PDF generation fails. We therefore:
      1. Strip non-ASCII characters from every dynamic string
      2. Use plain text section headers (no emojis)
      3. Catch exceptions and surface a useful error to the caller
    """
    if not HAS_REPORTLAB:
        return None

    def _ascii(text):
        """Drop characters Helvetica can't render (emojis, Arabic, etc).
        Returns a clean ASCII-only string, safe for reportlab Paragraphs."""
        if text is None:
            return ''
        s = str(text)
        # Keep printable ASCII + common punctuation/whitespace
        return ''.join(c if 32 <= ord(c) <= 126 or c in '\n\t' else ' '
                       for c in s).strip() or '-'

    try:
        buf = io.BytesIO()
        doc = SimpleDocTemplate(buf, pagesize=A4,
                                topMargin=2*cm, bottomMargin=2*cm,
                                leftMargin=2*cm, rightMargin=2*cm)
        styles = getSampleStyleSheet()
        title_style = ParagraphStyle(
            'CustomTitle', parent=styles['Heading1'],
            fontSize=24, textColor=colors.HexColor('#00d4ff'),
            alignment=1, spaceAfter=20)
        h2_style = ParagraphStyle(
            'CustomH2', parent=styles['Heading2'],
            fontSize=16, textColor=colors.HexColor('#ff4b2b'),
            spaceBefore=15, spaceAfter=10)
        body_style = ParagraphStyle(
            'CustomBody', parent=styles['Normal'],
            fontSize=11, leading=14, spaceAfter=8)

        story = []

        # --- Cover ---
        story.append(Spacer(1, 3*cm))
        story.append(Paragraph("Advanced IDS / IPS", title_style))
        story.append(Paragraph(
            "Comprehensive Defense Simulation", title_style))
        story.append(Spacer(1, 1*cm))
        story.append(Paragraph(
            f"<b>Generated:</b> {datetime.now().strftime('%Y-%m-%d %H:%M:%S')}",
            body_style))
        story.append(Paragraph(
            f"<b>System Mode:</b> {'AUTO' if st.session_state.auto_mode else 'MANUAL'}",
            body_style))
        story.append(Paragraph(
            f"<b>Devices Monitored:</b> {len(devices)}",
            body_style))
        story.append(PageBreak())

        # --- Executive Summary ---
        story.append(Paragraph("Executive Summary", h2_style))
        summary_data = [
            ['Metric', 'Value'],
            ['Total Attacks Detected', str(st.session_state.total_attacks)],
            ['Total Blocked', str(st.session_state.total_blocked)],
            ['Block Rate', f"{(st.session_state.total_blocked/max(st.session_state.total_attacks,1))*100:.1f}%"],
            ['Active Blocked IPs', str(len(st.session_state.blocked_ips))],
            ['Honeypot Redirects', str(len(st.session_state.honeypot_ips))],
            ['Pending Decisions', str(len(st.session_state.pending_decisions))],
        ]
        t = Table(summary_data, colWidths=[8*cm, 6*cm])
        t.setStyle(TableStyle([
            ('BACKGROUND', (0,0), (-1,0), colors.HexColor('#00d4ff')),
            ('TEXTCOLOR', (0,0), (-1,0), colors.white),
            ('ALIGN', (0,0), (-1,-1), 'LEFT'),
            ('FONTNAME', (0,0), (-1,0), 'Helvetica-Bold'),
            ('FONTSIZE', (0,0), (-1,0), 12),
            ('GRID', (0,0), (-1,-1), 0.5, colors.grey),
            ('ROWBACKGROUNDS', (0,1), (-1,-1),
             [colors.HexColor('#f5f5f5'), colors.white]),
        ]))
        story.append(t)
        story.append(Spacer(1, 0.5*cm))

        # --- ML Performance ---
        story.append(Paragraph("Machine Learning Performance", h2_style))
        ml_data = [
            ['Metric', 'Score', 'Interpretation'],
            ['Accuracy', f'{accuracy:.4f}', 'Overall correctness'],
            ['Precision', f'{precision:.4f}', 'Of detected attacks, % were real'],
            ['Recall', f'{recall:.4f}', 'Of real attacks, % were caught'],
            ['F1 Score', f'{f1:.4f}', 'Harmonic mean of P and R'],
        ]
        t = Table(ml_data, colWidths=[4*cm, 3*cm, 7*cm])
        t.setStyle(TableStyle([
            ('BACKGROUND', (0,0), (-1,0), colors.HexColor('#ff4b2b')),
            ('TEXTCOLOR', (0,0), (-1,0), colors.white),
            ('FONTNAME', (0,0), (-1,0), 'Helvetica-Bold'),
            ('GRID', (0,0), (-1,-1), 0.5, colors.grey),
            ('ROWBACKGROUNDS', (0,1), (-1,-1),
             [colors.HexColor('#f5f5f5'), colors.white]),
        ]))
        story.append(t)
        story.append(PageBreak())

        # --- Attack Log ---
        story.append(Paragraph("Attack Log (Latest 20)", h2_style))
        if attack_log:
            log_data = [['Time', 'Type', 'Severity', 'Source', 'Target', 'Action']]
            for atk in attack_log[-20:][::-1]:
                log_data.append([
                    _ascii(atk.get('timestamp', ''))[:19],
                    _ascii(atk.get('name', ''))[:20],
                    _ascii(atk.get('severity', '')),
                    _ascii(atk.get('src_ip', ''))[:15],
                    _ascii(atk.get('target_id', ''))[:8],
                    _ascii(atk.get('action_taken', 'Pending'))[:25],
                ])
            t = Table(log_data,
                      colWidths=[3*cm, 3*cm, 2*cm, 2.5*cm, 1.8*cm, 4*cm])
            t.setStyle(TableStyle([
                ('BACKGROUND', (0,0), (-1,0), colors.HexColor('#1e3c72')),
                ('TEXTCOLOR', (0,0), (-1,0), colors.white),
                ('FONTNAME', (0,0), (-1,0), 'Helvetica-Bold'),
                ('FONTSIZE', (0,0), (-1,-1), 8),
                ('GRID', (0,0), (-1,-1), 0.3, colors.grey),
                ('ROWBACKGROUNDS', (0,1), (-1,-1),
                 [colors.HexColor('#fafafa'), colors.white]),
            ]))
            story.append(t)
        else:
            story.append(Paragraph("No attacks recorded.", body_style))

        # --- Recommendations ---
        story.append(PageBreak())
        story.append(Paragraph("Security Recommendations", h2_style))
        recommendations = [
            "- Maintain Defense-in-Depth strategy with multiple security layers",
            "- Keep Random Forest + Isolation Forest as complementary models",
            "- Enable AUTO mode during off-hours for unattended protection",
            "- Review pending decisions within 7 seconds (auto-handle backup)",
            "- Use Telegram bot integration for remote incident response",
            "- Maintain regular backups (offline) against ransomware",
            "- Update security signatures weekly",
            "- Conduct phishing-awareness training quarterly",
        ]
        for r in recommendations:
            story.append(Paragraph(r, body_style))

        story.append(Spacer(1, 1*cm))
        story.append(Paragraph(
            "<i>This report was generated automatically by the IDS / IPS System.</i>",
            body_style))

        # Build PDF
        doc.build(story)
        buf.seek(0)
        return buf.read()
    except Exception as e:
        # 🔑 Surface the real error so future failures aren't silent.
        # We print to stderr (visible in Streamlit Cloud logs) but still
        # return None so the calling code's UI message is preserved.
        import sys
        print(f"[PDF generation error] {type(e).__name__}: {e}",
              file=sys.stderr)
        return None



@st.cache_data
def build_network(quality='Medium', seed=42):
    np.random.seed(seed)
    devices = []
    n_clients = {'Low': 15, 'Medium': 30, 'High': 30}.get(quality, 30)

    devices.append({
        'id': 'FW-01', 'type': 'firewall', 'ip': '10.0.0.1',
        'x': 0, 'y': 0, 'z': 0, 'size': 28, 'color': '#00ff88'
    })
    for i in range(5):
        a = 2 * np.pi * i / 5
        devices.append({
            'id': f'SRV-{i+1:02d}', 'type': 'server', 'ip': f'10.0.1.{i+1}',
            'x': 3*np.cos(a), 'y': 3*np.sin(a), 'z': 2,
            'size': 20, 'color': '#00d4ff'
        })
    for i in range(4):
        a = 2 * np.pi * i / 4 + np.pi/8
        devices.append({
            'id': f'RTR-{i+1:02d}', 'type': 'router', 'ip': f'10.0.2.{i+1}',
            'x': 5*np.cos(a), 'y': 5*np.sin(a), 'z': 0,
            'size': 16, 'color': '#ffaa00'
        })
    for i in range(n_clients):
        a = 2 * np.pi * i / n_clients
        r = 7 + np.random.uniform(-0.5, 0.5)
        devices.append({
            'id': f'PC-{i+1:02d}', 'type': 'client', 'ip': f'192.168.1.{i+10}',
            'x': r*np.cos(a), 'y': r*np.sin(a),
            'z': -2 + np.random.uniform(-1, 1),
            'size': 11, 'color': '#aaaaaa'
        })
    return devices


# =====================================================================
# 3D Renderer
# =====================================================================
def render_3d_network(devices, active_attacks=None, blocked_ips=None,
                      traffic_flows=None, attack_pulses=None,
                      quality='Medium', title='🌐 Network Topology — 3D Live View'):
    active_attacks = active_attacks or []
    blocked_ips    = blocked_ips    or set()
    traffic_flows  = traffic_flows  or []
    attack_pulses  = attack_pulses  or []

    fig = go.Figure()
    fw = devices[0]
    line_op = 0.2 if quality == 'Low' else 0.4

    for d in devices[1:6]:
        fig.add_trace(go.Scatter3d(
            x=[fw['x'],d['x']], y=[fw['y'],d['y']], z=[fw['z'],d['z']],
            mode='lines',
            line=dict(color=f'rgba(100,200,255,{line_op})', width=2),
            hoverinfo='skip', showlegend=False))
    for d in devices[6:10]:
        fig.add_trace(go.Scatter3d(
            x=[fw['x'],d['x']], y=[fw['y'],d['y']], z=[fw['z'],d['z']],
            mode='lines',
            line=dict(color=f'rgba(255,170,0,{line_op})', width=2),
            hoverinfo='skip', showlegend=False))

    if quality != 'Low':
        routers = devices[6:10]
        for c in devices[10:]:
            n = min(routers, key=lambda r:(r['x']-c['x'])**2+(r['y']-c['y'])**2)
            fig.add_trace(go.Scatter3d(
                x=[n['x'],c['x']], y=[n['y'],c['y']], z=[n['z'],c['z']],
                mode='lines',
                line=dict(color=f'rgba(150,150,150,{line_op*0.5})', width=1),
                hoverinfo='skip', showlegend=False))

    for src_id, dst_id, mal in traffic_flows:
        s = next((d for d in devices if d['id'] == src_id), None)
        t = next((d for d in devices if d['id'] == dst_id), None)
        if s and t:
            color = 'rgba(255,0,50,0.95)' if mal else 'rgba(0,255,150,0.7)'
            width = (8 if quality == 'High' else 6) if mal else (4 if quality == 'High' else 3)
            fig.add_trace(go.Scatter3d(
                x=[s['x'],t['x']], y=[s['y'],t['y']], z=[s['z'],t['z']],
                mode='lines',
                line=dict(color=color, width=width),
                hoverinfo='skip', showlegend=False))

    if quality == 'High' and attack_pulses:
        for pulse in attack_pulses:
            d = next((dev for dev in devices if dev['id'] == pulse['target']), None)
            if d:
                for radius in [1.5, 2.5, 3.5]:
                    theta = np.linspace(0, 2*np.pi, 30)
                    fig.add_trace(go.Scatter3d(
                        x=d['x'] + radius*np.cos(theta),
                        y=d['y'] + radius*np.sin(theta),
                        z=[d['z']]*30,
                        mode='lines',
                        line=dict(color=f'rgba(255,0,0,{0.5/radius})', width=2),
                        hoverinfo='skip', showlegend=False))

    symbols = {'firewall':'diamond', 'server':'square',
               'router':'circle', 'client':'circle'}
    for dtype, sym in symbols.items():
        td = [d for d in devices if d['type'] == dtype]
        if not td: continue
        colors, sizes, texts = [], [], []
        for d in td:
            if d['id'] in active_attacks:
                colors.append('#ff0033')
                sizes.append(d['size'] * (1.8 if quality == 'High' else 1.5))
            elif d['ip'] in blocked_ips:
                colors.append('#660000'); sizes.append(d['size'])
            else:
                colors.append(d['color']); sizes.append(d['size'])
            status = ("🚨 UNDER ATTACK" if d['id'] in active_attacks else
                      "🚫 BLOCKED" if d['ip'] in blocked_ips else "✅ Active")
            texts.append(f"<b>{d['id']}</b><br>Type: {d['type']}<br>"
                         f"IP: {d['ip']}<br>Status: {status}")

        fig.add_trace(go.Scatter3d(
            x=[d['x'] for d in td],
            y=[d['y'] for d in td],
            z=[d['z'] for d in td],
            mode='markers+text',
            marker=dict(size=sizes, color=colors, symbol=sym,
                        line=dict(color='white', width=1), opacity=0.95),
            text=[d['id'] for d in td],
            textposition='top center',
            textfont=dict(size=9, color='white'),
            hovertext=texts, hoverinfo='text',
            name=dtype.title()))

    fig.update_layout(
        scene=dict(
            xaxis=dict(visible=False), yaxis=dict(visible=False), zaxis=dict(visible=False),
            bgcolor='rgba(10,10,30,1)',
            camera=dict(eye=dict(x=1.5, y=1.5, z=1.2))),
        paper_bgcolor='rgba(10,10,30,1)',
        font=dict(color='white'),
        margin=dict(l=0, r=0, t=30, b=0),
        height=600,
        legend=dict(x=0.02, y=0.98, bgcolor='rgba(0,0,0,0.5)',
                    bordercolor='rgba(255,255,255,0.2)', borderwidth=1),
        title=dict(text=title, font=dict(size=18, color='#00d4ff'), x=0.5))
    return fig


