def threat_gauge(value, title="Threat Level"):
    fig = go.Figure(go.Indicator(
        mode='gauge+number', value=value,
        title={'text': title, 'font': {'size': 16, 'color': 'white'}},
        gauge={
            'axis': {'range': [0,100], 'tickcolor': 'white'},
            'bar': {'color': '#ff4b2b' if value > 70 else
                            '#ffaa00' if value > 40 else '#00ff88'},
            'bgcolor': 'rgba(0,0,0,0)',
            'steps': [
                {'range':[0,40],   'color':'rgba(0,255,136,0.3)'},
                {'range':[40,70],  'color':'rgba(255,170,0,0.3)'},
                {'range':[70,100], 'color':'rgba(255,75,43,0.3)'}
            ],
            'threshold': {'line':{'color':'white','width':3},
                          'thickness':0.75, 'value':value}}))
    fig.update_layout(
        paper_bgcolor='rgba(0,0,0,0)',
        font={'color':'white'}, height=250,
        margin=dict(l=20, r=20, t=40, b=20))
    return fig


