def generate_attack(attack_key, devices):
    """Generate a realistic attack event."""
    info = ATTACK_TYPES[attack_key]
    src_ip = (f"{random.randint(1,255)}.{random.randint(1,255)}."
              f"{random.randint(1,255)}.{random.randint(1,255)}")
    target_pool = [d for d in devices if d['type'] in ['server', 'router']]
    target = random.choice(target_pool)

    extras = {
        'DDoS':         {'packets/sec': random.randint(5000,50000)},
        'Port Scan':    {'ports_scanned': random.randint(50,1000)},
        'Brute Force':  {'failed_logins': random.randint(50,500)},
        'SQL Injection':{'queries': random.randint(10,200)},
        'Ransomware':   {'files_encrypted': random.randint(100,5000)},
        'MITM':         {'sessions_intercepted': random.randint(5,50)},
        'Phishing':     {'phish_attempts': random.randint(10,100)},
        'Zero-day':     {'exploit_attempts': random.randint(1,20)},
    }.get(attack_key, {})

    return {
        'timestamp':    datetime.now().strftime('%Y-%m-%d %H:%M:%S'),
        'attack_key':   attack_key,
        'src_ip':       src_ip,
        'target_id':    target['id'],
        'target_ip':    target['ip'],
        'name':         info['name'],
        'arabic':       info['arabic'],
        'severity':     info['severity'],
        'icon':         info['icon'],
        'color':        info['color'],
        'description':  info['description'],
        'recommended':  info['recommended'],
        'extras':       extras,
        'action_taken': None,
        'status':       'Pending'
    }


def handle_attack_auto(attack):
    """🆕 Auto-mode: SEPARATED Block vs Honeypot logic.

    The previous implementation conflated Block + Honeypot (technically
    contradictory). Now each attack type gets the right strategy:

    • DDoS / Ransomware → Block (no time to study, must cut traffic)
    • Port Scan / SQL Injection / XSS → Honeypot (worth observing/trapping)
    • MITM / Brute Force / Zero-day → Block (immediate threat)
    • Medium severity → Rate Limit
    """
    sev = attack['severity']
    akey = attack.get('attack_key', '')
    src_ip = attack['src_ip']

    # Decide strategy: Block vs Honeypot vs Rate Limit
    HONEYPOT_TYPES = {'port_scan', 'sql_injection', 'xss'}

    if sev == 'Critical':
        if akey in HONEYPOT_TYPES:
            # Worth observing — redirect to honeypot
            action = '🍯 تم تحويل المهاجم لمصيدة Honeypot للمراقبة'
            action_short = 'Honeypot'
            st.session_state.honeypot_ips.add(src_ip)
            # 🆕 Start honeypot session tracking
            _start_honeypot_session(src_ip, attack)
        else:
            # Immediate threat — block
            action = '🚫 تم حظر المصدر فوراً'
            action_short = 'Block'
            st.session_state.blocked_ips.add(src_ip)
    elif sev == 'High':
        if akey in HONEYPOT_TYPES:
            action = '🍯 تم تحويل المهاجم لمصيدة Honeypot'
            action_short = 'Honeypot'
            st.session_state.honeypot_ips.add(src_ip)
            _start_honeypot_session(src_ip, attack)
        else:
            action = '🚫 تم حظر المصدر'
            action_short = 'Block'
            st.session_state.blocked_ips.add(src_ip)
    else:  # Medium
        action = '⏱️ تم تحديد سرعة الاتصال (Rate Limit)'
        action_short = 'Rate Limit'
        st.session_state.blocked_ips.add(src_ip)

    attack['action_taken'] = action
    attack['action_short'] = action_short
    attack['status'] = 'Resolved'
    attack['blocked_ip'] = src_ip
    attack['undone'] = False
    st.session_state.total_blocked += 1
    return attack


def _start_honeypot_session(src_ip, attack):
    """🆕 Track a honeypot session — what the attacker tries while trapped.

    Simulates realistic attacker behavior so we can show evidence of the
    attacker's activities to the lecturer/audience.
    """
    sessions = st.session_state.honeypot_sessions
    if src_ip not in sessions:
        sessions[src_ip] = {
            'started_at': datetime.now().strftime('%Y-%m-%d %H:%M:%S'),
            'started_ts': time.time(),
            'attack_name': attack['name'],
            'attack_icon': attack['icon'],
            'commands_tried': random.randint(15, 80),
            'http_requests': random.randint(200, 2500),
            'files_attempted': random.sample([
                '/etc/passwd', '/etc/shadow', '/admin/config.php',
                '/backup/db.sql', '/var/log/auth.log', '/.env',
                '/wp-admin/', '/.git/config', '/api/users',
                '/phpinfo.php', '/server-status', '/.aws/credentials',
            ], k=random.randint(3, 6)),
            'tools_detected': random.sample([
                'nmap', 'sqlmap', 'hydra', 'metasploit',
                'nikto', 'dirb', 'wpscan', 'burp suite',
                'cURL/automated', 'python-requests', 'gobuster',
            ], k=random.randint(2, 4)),
            'duration_seconds': 0,  # updated on close
            'detected_at': None,    # set when honeypot is closed
        }


def _close_honeypot_session(src_ip):
    """Close a honeypot session and record final stats."""
    sessions = st.session_state.honeypot_sessions
    if src_ip in sessions and sessions[src_ip].get('detected_at') is None:
        sess = sessions[src_ip]
        sess['duration_seconds'] = int(time.time() - sess['started_ts'])
        sess['detected_at'] = datetime.now().strftime('%Y-%m-%d %H:%M:%S')


def log_auto_activation(reason, attack_name=None):
    """🆕 Log a moment when AUTO mode was activated automatically.

    Called whenever the 7-second timeout triggers and AUTO mode is
    forced ON. Also increments the activation counter that drives the
    "AUTO mode auto-activated" banner.
    """
    st.session_state.auto_activations_log.append({
        'time':         datetime.now().strftime('%H:%M:%S'),
        'date':         datetime.now().strftime('%Y-%m-%d'),
        'reason':       reason,
        'attack_name':  attack_name or '—',
    })
    # Keep last 50 only
    st.session_state.auto_activations_log = \
        st.session_state.auto_activations_log[-50:]


# =====================================================================
# 🎯 POST-DEFENSE VIEW — keeps the simulation visible for explaining
# =====================================================================
# After an attack is neutralized (in either AUTO or MANUAL mode), we
# hold the entire visual context — the 3D network with the attack edges
# faded, the threat chart, the attack metadata — on screen for a fixed
# window so the operator can narrate what happened (perfect for demos
# and academic defenses). Three exit paths:
#   1. Timer expires        → auto-clear
#   2. User clicks "Close"  → instant clear
#   3. New attack starts    → instant overwrite (the next attack takes over)
# =====================================================================
POST_DEFENSE_DURATION = 30  # seconds — chosen as a balance between
                            # "enough time to explain" and "not too long"


def start_post_defense_view(attack, mode='auto'):
    """Activate the 30-second post-defense view for an attack that was
    just neutralized.

    🔑 IDEMPOTENT: if the post-defense view is ALREADY active for the
    SAME attack (same target_id + src_ip + name), this is a no-op. This
    prevents the autorefresh from resetting the `until` timer every 2s,
    which previously caused the view to "stick" indefinitely in AUTO mode.

    For a genuinely NEW attack, the view overwrites the previous one
    (taking the new attack's 30-second window).
    """
    existing = st.session_state.get('post_defense_view')
    if existing and isinstance(existing, dict):
        e_atk = existing.get('attack', {})
        same_attack = (
            e_atk.get('target_id') == attack.get('target_id')
            and e_atk.get('src_ip') == attack.get('src_ip')
            and e_atk.get('name') == attack.get('name')
            and e_atk.get('timestamp') == attack.get('timestamp')
        )
        if same_attack:
            # Already showing this exact attack — leave timer alone
            return
    st.session_state.post_defense_view = {
        'attack':      attack,
        'mode':        mode,
        'started_at':  time.time(),
        'until':       time.time() + POST_DEFENSE_DURATION,
    }


def clear_post_defense_view():
    """Force-clear the post-defense view (user clicked Close, or timer
    expired during a render)."""
    st.session_state.post_defense_view = None


def post_defense_is_active():
    """True if a post-defense view is currently active AND its timer
    has not yet expired. Called on every page render to decide whether
    to show the held simulation.

    🔑 BUG FIX: previously this could leave a stale view on screen if
    the autorefresh fired exactly at the boundary. Now we explicitly
    null the session_state key when expired so subsequent reruns see
    a clean slate (no zombie views).
    """
    pdv = st.session_state.get('post_defense_view')
    if not pdv:
        return False
    if not isinstance(pdv, dict):
        # Corrupt state — defensive clear
        st.session_state.post_defense_view = None
        return False
    if time.time() >= pdv.get('until', 0):
        # Expired during this render → auto-clean and return False
        st.session_state.post_defense_view = None
        return False
    return True


def trigger_auto_activation(attacks_handled, reason='7-second timeout'):
    """🆕 Activate AUTO mode globally + persistent banner.

    The banner stays until the user manually clicks "Restore MANUAL".

    🔑 WIDGET SYNC: also writes the widget-bound key (auto_mode_widget)
    so the sidebar toggle reflects the change visually on the next
    render — previously the toggle showed OFF even though the system
    was actively running in AUTO mode (very confusing for the user).
    """
    auto_was_off = not st.session_state.auto_mode
    st.session_state.auto_mode = True
    # 🆕 Sync the widget-bound key so the toggle visually flips ON
    st.session_state.auto_mode_widget = True

    if auto_was_off:
        st.session_state.auto_was_auto_activated = True
        st.session_state.auto_activated_count = attacks_handled
    else:
        # Already auto-activated — increment counter
        st.session_state.auto_activated_count += attacks_handled

    log_auto_activation(reason)
    return auto_was_off


