def telegram_send_message(token, chat_id, message, reply_markup=None):
    """Send a text message via Telegram bot (with short timeout)."""
    try:
        url = f"https://api.telegram.org/bot{token}/sendMessage"
        payload = {
            'chat_id': chat_id, 'text': message, 'parse_mode': 'HTML'
        }
        if reply_markup is not None:
            payload['reply_markup'] = reply_markup
        # Short timeout: 5s for sending (we tolerate slight delay but not freeze)
        r = requests.post(url, json=payload, timeout=5)
        data = r.json()
        if data.get('ok'):
            return data.get('result', {}).get('message_id')
        return None
    except Exception:
        return None


def telegram_send_photo(token, chat_id, image_bytes, caption=''):
    """Send a photo via Telegram bot."""
    try:
        url = f"https://api.telegram.org/bot{token}/sendPhoto"
        files = {'photo': ('img.png', image_bytes, 'image/png')}
        data = {'chat_id': chat_id, 'caption': caption}
        # Photos can be slower — 10s timeout
        r = requests.post(url, data=data, files=files, timeout=10)
        return r.json().get('ok', False)
    except Exception:
        return False


def telegram_test_connection(token, chat_id):
    """Test Telegram bot connection — quick timeout."""
    try:
        r = requests.get(f"https://api.telegram.org/bot{token}/getMe", timeout=5)
        if not r.json().get('ok'):
            return False, "❌ Token غير صحيح"
        # Test send
        r2 = requests.post(
            f"https://api.telegram.org/bot{token}/sendMessage",
            json={'chat_id': chat_id,
                  'text': '✅ IDS/IPS Test - الاتصال ناجح!'},
            timeout=5)
        if r2.json().get('ok'):
            # Reset error counter on successful test
            st.session_state.tg_error_count = 0
            return True, "✅ تم إرسال رسالة اختبار بنجاح"
        return False, f"❌ Chat ID خطأ: {r2.json().get('description', '?')}"
    except Exception as e:
        return False, f"❌ خطأ: {str(e)[:80]}"


def telegram_answer_callback(token, callback_query_id, text=''):
    """Acknowledge a callback_query — short timeout."""
    try:
        url = f"https://api.telegram.org/bot{token}/answerCallbackQuery"
        requests.post(url, json={
            'callback_query_id': callback_query_id,
            'text': text[:200] if text else ''
        }, timeout=3)
        return True
    except Exception:
        return False


def build_inline_keyboard(buttons):
    """Build a Telegram inline keyboard from a list of button rows.

    Each button is a tuple (text, callback_data).
    Returns a dict ready to pass as reply_markup.

    Example:
        build_inline_keyboard([
            [("🚫 Block", "block:5"), ("🍯 Honeypot", "honeypot:5")],
            [("✅ Allow", "allow:5")]
        ])
    """
    return {
        'inline_keyboard': [
            [{'text': text, 'callback_data': cb} for text, cb in row]
            for row in buttons
        ]
    }


