# =====================================================================
# 🔌 Internet connectivity probe — caches result for 5 seconds
# =====================================================================
def _telegram_internet_ok():
    """Quick online check using a short HTTPS HEAD probe.

    🔑 IMPORTANT: This uses HTTPS (not raw TCP socket) because Streamlit
    Cloud sometimes blocks outbound TCP on port 443 while still allowing
    HTTPS via the standard library's HTTP stack. Previously this used
    socket.create_connection() with a 0.3s timeout, which silently failed
    in those environments and made the entire Telegram subsystem appear
    broken (alerts never sent, even though the actual API was reachable).

    Why this exists:
      requests.post() with timeout=5 will block the UI for 5 seconds per
      call when the connection is truly dead. With multiple back-to-back
      sends, that adds up. This probe is fast (~0.8s tops) and matches
      the actual transport that send_telegram_alert uses, so a positive
      result reliably predicts that send_telegram_alert will succeed.

    Result is cached for 5 seconds to avoid spamming the API host.

    DEFAULT TO TRUE on probe errors: we'd rather attempt the send and
    let its own timeout handle a true outage than block on a probe that
    might be wrong. The cost of an extra 5s timeout once per outage is
    far smaller than silently dropping every Telegram message because
    the probe failed for an unrelated reason.
    """
    cache = st.session_state.get('_tg_net_cache', {'ts': 0, 'ok': True})
    now = time.time()
    if now - cache['ts'] < 5.0:
        return cache['ok']
    ok = True  # Default optimistic — see docstring
    try:
        # HEAD request to Telegram's root — minimal traffic, real HTTPS
        r = requests.head('https://api.telegram.org/', timeout=0.8,
                          allow_redirects=False)
        # Any HTTP response (even 404) means the network is reachable
        ok = bool(r.status_code)
    except requests.exceptions.Timeout:
        # Slow network — but might still work for the actual API call
        ok = True
    except requests.exceptions.ConnectionError:
        # Truly offline or DNS failure
        ok = False
    except Exception:
        # Anything unexpected — be optimistic, let the real call decide
        ok = True
    st.session_state['_tg_net_cache'] = {'ts': now, 'ok': ok}
    return ok


def send_telegram_alert(attack, phase='alert'):
    """🆕 Send Telegram alert — REVISED: text first, images after.

    Phases:
      'alert'    → Detection notification.
                   • In MANUAL: 3 inline buttons (Defend / Pass / Toggle AUTO)
                   • In AUTO:   no buttons (attack still being handled)
      'resolved' → Confirmation message after handling.
                   • In AUTO: 2 buttons (Undo + Toggle AUTO)
                   • In MANUAL: no buttons (decision already made)
      'timeout'  → Auto-handled because no manual response within 7s.

    Sequence: text first, then image attachments — so the user sees
    the message immediately on their phone.

    🔌 INTERNET PRE-CHECK: A 0.3s socket probe runs first. If the network
    is down, we abort immediately rather than burning 5×N seconds on HTTP
    timeouts (where N is the number of consecutive sends). This is the
    fix for two complaints simultaneously: (a) UI freezes when offline,
    (b) back-to-back alert+resolved calls in AUTO mode appeared sluggish.
    """
    if not st.session_state.tg_enabled:
        return None
    if not _telegram_internet_ok():
        # Silently skip — no point queuing reties and freezing the UI.
        return None
    token = st.session_state.tg_token.strip()
    chat_id = st.session_state.tg_chat_id.strip()
    if not token or not chat_id:
        return None

    sev_emoji = {'Critical':'🔴', 'High':'🟠', 'Medium':'🟡'}.get(attack['severity'], '⚪')
    is_auto = st.session_state.auto_mode

    # Stable attack index (used for callback button data)
    attack_idx = attack.get('tg_index')
    if attack_idx is None:
        attack_idx = len(st.session_state.attack_log) + random.randint(1000, 9999)
        attack['tg_index'] = attack_idx

    # ═══════════════════════════════════════════════════════════════
    # PHASE: RESOLVED  (after handling, manual or auto)
    # ═══════════════════════════════════════════════════════════════
    if phase == 'resolved':
        mode_label = '🤖 AUTO' if is_auto else '👤 MANUAL'
        action_taken = attack.get('action_taken', 'Handled')
        action_short = attack.get('action_short', '')

        # 🆕 Smart action description (no contradictory "Block + Honeypot")
        if 'Honeypot' in action_taken or action_short == 'Honeypot':
            action_line = "🛡️ تم تحويل المهاجم لمصيدة Honeypot للمراقبة"
        elif 'Rate Limit' in action_taken or 'تحديد' in action_taken or action_short == 'Rate Limit':
            action_line = "🛡️ تم تحديد سرعة الاتصال (Rate Limit)"
        elif 'Pass' in action_taken or 'تمرير' in action_taken or 'Allow' in action_taken or 'False' in action_taken:
            action_line = "✅ تم تمرير الاتصال (لم يكن هجوماً)"
        else:
            action_line = "🛡️ تم حظر المصدر فوراً"

        resolved_msg = (
            f"✅✅✅ <b>تم صد الهجوم بنجاح</b> ✅✅✅\n\n"
            f"{attack['icon']} <b>الهجوم:</b> {attack['name']}\n"
            f"📛 <i>{attack['arabic']}</i>\n"
            f"🎯 <b>الهدف:</b> {attack['target_id']} ({attack['target_ip']})\n"
            f"📍 <b>المصدر:</b> <code>{attack['src_ip']}</code>\n\n"
            f"{action_line}\n"
            f"⚙️ <b>الوضع:</b> {mode_label}\n"
            f"⏰ <b>الوقت:</b> {datetime.now().strftime('%Y-%m-%d %H:%M:%S')}\n\n"
            f"🛡️ <b>النظام آمن — العمل طبيعي</b>\n"
            f"━━━━━━━━━━━━━━━━━━━\n"
            f"🛡️ IDS/IPS System Notification"
        )

        markup = None
        if is_auto and not attack.get('undone'):
            if 'Honeypot' in action_taken:
                undo_label = "↩️ سحب من Honeypot"
            elif 'Rate Limit' in action_taken:
                undo_label = "↩️ إزالة Rate Limit"
            else:
                undo_label = "↩️ إلغاء الحظر"
            markup = build_inline_keyboard([
                [(undo_label, f"undo:{attack_idx}")],
                [("⏸️ إيقاف الوضع التلقائي", f"disable_auto:{attack_idx}")],
            ])

        msg_id = telegram_send_message(token, chat_id, resolved_msg, reply_markup=markup)
        if msg_id and markup:
            st.session_state.tg_message_actions[str(msg_id)] = {
                'attack_idx': attack_idx, 'taken': False, 'phase': 'resolved'
            }
        return msg_id

    # ═══════════════════════════════════════════════════════════════
    # PHASE: TIMEOUT  (auto-handled because no manual reply in 7s)
    # ═══════════════════════════════════════════════════════════════
    if phase == 'timeout':
        action_taken = attack.get('action_taken', 'Auto-handled')
        if 'Honeypot' in action_taken:
            action_line = "🛡️ تم تحويل المهاجم لمصيدة Honeypot للمراقبة"
        elif 'Rate Limit' in action_taken or 'تحديد' in action_taken:
            action_line = "🛡️ تم تحديد سرعة الاتصال"
        else:
            action_line = "🛡️ تم حظر المصدر فوراً"

        timeout_msg = (
            f"🤖🔥 <b>تم تفعيل وضع التصدي التلقائي</b>\n\n"
            f"⚠️ فعّل النظام وضع التحكم التلقائي وقام بصد الهجوم "
            f"لأنه لم يتلقَّ أي أمر من القيادة خلال 7 ثوان.\n\n"
            f"✅ <b>تم صد الهجوم بنجاح:</b>\n"
            f"   {attack['icon']} {attack['name']}\n"
            f"   🎯 الهدف: {attack['target_id']}\n"
            f"   📍 المصدر: <code>{attack['src_ip']}</code>\n"
            f"   {action_line}\n\n"
            f"🔥 <b>وضع AUTO نشط الآن</b> — سيحمي الشبكة من الهجمات القادمة\n"
            f"⏰ {datetime.now().strftime('%H:%M:%S')}\n"
            f"━━━━━━━━━━━━━━━━━━━"
        )
        markup = build_inline_keyboard([
            [("↩️ تراجع عن المعالجة", f"undo:{attack_idx}")],
            [("⏸️ إيقاف الوضع التلقائي", f"disable_auto:{attack_idx}")],
        ])
        msg_id = telegram_send_message(token, chat_id, timeout_msg, reply_markup=markup)
        return msg_id

    # ═══════════════════════════════════════════════════════════════
    # PHASE: ALERT  (initial detection)
    # ═══════════════════════════════════════════════════════════════
    extras_text = "".join(f"• {k}: <b>{v:,}</b>\n" for k, v in attack['extras'].items())

    msg = (
        f"🚨🚨🚨 <b>SECURITY ALERT</b> 🚨🚨🚨\n\n"
        f"{attack['icon']} <b>Attack:</b> {attack['name']}\n"
        f"📛 <i>{attack['arabic']}</i>\n"
        f"{sev_emoji} <b>Severity:</b> {attack['severity']}\n\n"
        f"📍 <b>Source IP:</b> <code>{attack['src_ip']}</code>\n"
        f"🎯 <b>Target:</b> {attack['target_id']} ({attack['target_ip']})\n"
        f"⏰ <b>Time:</b> {attack['timestamp']}\n\n"
        f"📊 <b>Details:</b>\n{extras_text}\n"
        f"🛡️ <b>Recommended:</b> {attack['recommended']}\n"
        f"⚙️ <b>Mode:</b> {'🤖 AUTO' if is_auto else '👤 MANUAL'}\n"
    )
    if attack.get('action_taken'):
        msg += f"\n✅ <b>Action Taken:</b> {attack['action_taken']}\n"
    msg += "\n━━━━━━━━━━━━━━━━━━━\n🛡️ IDS/IPS System Alert"

    # Build the 3-button MANUAL keyboard
    markup = None
    if not is_auto:
        msg += ("\n\n⏰ <b>سيتم تفعيل التصدي التلقائي خلال 7 ثوان</b> "
                "إذا لم يصل أمر")
        markup = build_inline_keyboard([
            [("🛡️ تصدّي", f"defend:{attack_idx}")],
            [("✅ تمرير (False Alarm)", f"pass:{attack_idx}")],
            [("⚙️ تفعيل التصدي التلقائي", f"enable_auto:{attack_idx}")],
        ])

    # 🆕 SEND TEXT FIRST so user sees message immediately on phone
    msg_id = telegram_send_message(token, chat_id, msg, reply_markup=markup)
    if msg_id and markup:
        st.session_state.tg_message_actions[str(msg_id)] = {
            'attack_idx': attack_idx, 'taken': False, 'phase': 'alert'
        }
        # Track pending alert for 7s timeout (MANUAL only)
        if not is_auto:
            st.session_state.tg_pending_alerts[str(attack_idx)] = {
                'deadline': time.time() + 7,
                'attack': attack,
                'message_id': msg_id,
            }

    # 🆕 SEND IMAGES AFTER (they take longer to upload)
    if st.session_state.tg_send_image:
        try:
            img = network_to_image(
                st.session_state.devices,
                [attack['target_id']],
                st.session_state.blocked_ips,
                [(random.choice([d['id'] for d in st.session_state.devices
                                if d['type']=='client']), attack['target_id'], True)])
            if img:
                telegram_send_photo(token, chat_id, img,
                                  caption=f"🎯 Network View - {attack['name']}")
        except Exception:
            pass

    if st.session_state.tg_send_chart:
        try:
            chart_img = attack_chart_to_image(attack)
            if chart_img:
                telegram_send_photo(token, chat_id, chart_img,
                                  caption=f"📊 Attack Metrics - {attack['name']}")
        except Exception:
            pass

    return msg_id


def telegram_poll_callbacks():
    """🆕 Poll Telegram for new callback_query AND message updates.

    Critical fixes:
      - Short timeout (2s) so a slow network doesn't freeze the UI
      - Error counter: 3 consecutive failures → disable polling for 30s
      - Returns immediately if token is invalid or empty
      - 🔌 Internet pre-check (0.3s) — skip the 2s HTTP timeout entirely
        when the connection is dead; cached for 5s to avoid spam.
      - Returns dict with 'callbacks' and 'messages' keys
    """
    if not st.session_state.tg_enabled:
        return {'callbacks': [], 'messages': []}
    if not _telegram_internet_ok():
        return {'callbacks': [], 'messages': []}
    token = st.session_state.tg_token.strip()
    if not token or len(token) < 20:
        return {'callbacks': [], 'messages': []}

    # Circuit breaker
    error_count = st.session_state.get('tg_error_count', 0)
    last_error_time = st.session_state.get('tg_last_error_time', 0)
    if error_count >= 3 and (time.time() - last_error_time) < 30:
        return {'callbacks': [], 'messages': []}

    try:
        offset = st.session_state.tg_last_update_id + 1
        url = f"https://api.telegram.org/bot{token}/getUpdates"
        r = requests.get(url, params={
            'offset': offset, 'timeout': 0,
            'allowed_updates': '["callback_query","message"]'
        }, timeout=2)
        data = r.json()
        if not data.get('ok'):
            st.session_state.tg_error_count = error_count + 1
            st.session_state.tg_last_error_time = time.time()
            return {'callbacks': [], 'messages': []}
        st.session_state.tg_error_count = 0
        callbacks, messages = [], []
        for upd in data.get('result', []):
            st.session_state.tg_last_update_id = max(
                st.session_state.tg_last_update_id, upd['update_id'])
            if 'callback_query' in upd:
                callbacks.append(upd['callback_query'])
            elif 'message' in upd and 'text' in upd['message']:
                messages.append(upd['message'])
        return {'callbacks': callbacks, 'messages': messages}
    except Exception:
        st.session_state.tg_error_count = error_count + 1
        st.session_state.tg_last_error_time = time.time()
        return {'callbacks': [], 'messages': []}


def handle_telegram_message(msg, token, chat_id):
    """🆕 Handle text commands from Telegram (e.g., /status, /auto_on)."""
    text = msg.get('text', '').strip().lower()
    if text in ('/status', '/state'):
        # Compose status report
        ss = st.session_state
        mode = '🤖 AUTO' if ss.auto_mode else '👤 MANUAL'
        pending = len(ss.pending_decisions) + len(ss.tg_pending_alerts)
        total = ss.total_attacks
        blocked = ss.total_blocked
        active = '🚨 نعم' if ss.get('active_attack_session') else '✅ لا'
        active_name = ''
        if ss.get('active_attack_session'):
            a = ss.active_attack_session.get('attack', {})
            active_name = f"\n   ↳ <b>{a.get('name','?')}</b> → {a.get('target_id','?')}"
        report = (
            f"📊 <b>تقرير حالة النظام</b>\n\n"
            f"🛡️ <b>الوضع:</b> {mode}\n"
            f"🚨 <b>هجوم نشط:</b> {active}{active_name}\n"
            f"⏳ <b>هجمات معلقة:</b> {pending}\n"
            f"📈 <b>إجمالي الهجمات:</b> {total}\n"
            f"🚫 <b>المحظورة:</b> {blocked}\n"
            f"⏰ <b>الوقت:</b> {datetime.now().strftime('%H:%M:%S')}"
        )
        telegram_send_message(token, chat_id, report)
        return True
    if text in ('/auto_on', '/auto', '/autoon'):
        st.session_state.auto_mode = True
        log_auto_activation('Telegram /auto_on command')
        telegram_send_message(token, chat_id,
            "✅ <b>تم تفعيل AUTO Mode</b>\n🤖 النظام في وضع التصدي التلقائي")
        return True
    if text in ('/auto_off', '/manual', '/autooff'):
        st.session_state.auto_mode = False
        st.session_state.auto_was_auto_activated = False
        st.session_state.auto_activated_count = 0
        telegram_send_message(token, chat_id,
            "⏸️ <b>تم إيقاف AUTO Mode</b>\n👤 النظام في الوضع اليدوي")
        return True
    if text in ('/help', '/start'):
        help_msg = (
            "🛡️ <b>أوامر بوت IDS/IPS</b>\n\n"
            "/status — تقرير حالة النظام\n"
            "/auto_on — تفعيل التصدي التلقائي\n"
            "/auto_off — إيقاف التصدي التلقائي\n"
            "/help — هذه القائمة"
        )
        telegram_send_message(token, chat_id, help_msg)
        return True
    return False


def process_telegram_callbacks():
    """🔄 Apply any pending Telegram button presses to the session state.

    This is the heart of the interactive bot. It:
      1. Polls Telegram for new callbacks
      2. Parses each callback_data (format: 'action:attack_idx')
      3. Looks up the attack in session_state.attack_log
      4. Applies the action (override-style — any new command supersedes
         the previous one)
      5. Sends a confirmation message back with the next logical buttons
      6. Logs the action in tg_actions_log for display in the sidebar

    Returns:
        Number of actions processed (callbacks + messages combined).
    """
    poll = telegram_poll_callbacks()
    callbacks = poll.get('callbacks', [])
    messages = poll.get('messages', [])
    if not callbacks and not messages:
        return 0

    token = st.session_state.tg_token.strip()
    chat_id = st.session_state.tg_chat_id.strip()
    processed = 0

    # 🆕 Handle text commands (/status, /auto_on, /auto_off, /help)
    for msg in messages:
        try:
            if handle_telegram_message(msg, token, chat_id):
                processed += 1
        except Exception:
            pass

    for cb in callbacks:
        cb_id = cb.get('id')
        cb_data = cb.get('data', '')
        try:
            action, attack_idx_str = cb_data.split(':', 1)
            attack_idx = int(attack_idx_str)
        except ValueError:
            telegram_answer_callback(token, cb_id, "❌ Invalid command")
            continue

        # Find the attack
        attack = None
        for a in st.session_state.attack_log:
            if a.get('tg_index') == attack_idx:
                attack = a
                break

        if attack is None and action not in ('disable_auto', 'enable_auto'):
            telegram_answer_callback(token, cb_id, "❌ Attack not found")
            continue

        # Dispatch by action type
        confirmation = _apply_telegram_action(action, attack, token, chat_id)
        telegram_answer_callback(token, cb_id, confirmation['toast'])

        # Log the action for display in the app
        st.session_state.tg_actions_log.append({
            'time': datetime.now().strftime('%H:%M:%S'),
            'action': action,
            'attack': attack['name'] if attack else '—',
            'result': confirmation['toast']
        })
        # Keep last 20 entries
        st.session_state.tg_actions_log = st.session_state.tg_actions_log[-20:]
        processed += 1

    return processed


def _apply_telegram_action(action, attack, token, chat_id):
    """🆕 Apply a single Telegram action to the session state.

    Action types:
      'defend'       → 🛡️ Block attack (combined block + handle)
      'pass'         → ✅ Mark as false alarm (allow traffic)
      'enable_auto'  → ⚙️ Turn on AUTO mode globally
      'disable_auto' → ⏸️ Turn off AUTO mode globally
      'undo'         → ↩️ Reverse a previous action
      'handle_auto'  → 🤖 Apply auto-defense to this specific attack
      'block'        → 🚫 Block (legacy, for backward compatibility)
      'honeypot'     → 🍯 Redirect to honeypot
      'allow'        → ✅ Allow (legacy)

    Returns dict with 'toast' key for the brief Telegram callback ack.
    """
    now_str = datetime.now().strftime('%Y-%m-%d %H:%M:%S')

    # ─── AUTO mode toggle (no attack required) ───
    if action == 'disable_auto':
        st.session_state.auto_mode = False
        # Also clear any pending Telegram alerts (no longer auto-handled)
        markup = build_inline_keyboard([
            [("▶️ إعادة تشغيل التصدي التلقائي", "enable_auto:0")]
        ])
        telegram_send_message(token, chat_id,
            f"⏸️ <b>AUTO Mode Disabled</b>\n\n"
            f"النظام الآن في وضع <b>MANUAL</b>.\n"
            f"الهجمات القادمة ستنتظر قرارك.\n\n"
            f"⏰ {now_str}",
            reply_markup=markup)
        return {'toast': '⏸️ AUTO disabled'}

    if action == 'enable_auto':
        st.session_state.auto_mode = True
        markup = build_inline_keyboard([
            [("⏸️ إيقاف التصدي التلقائي", "disable_auto:0")]
        ])
        telegram_send_message(token, chat_id,
            f"▶️ <b>AUTO Mode Enabled</b>\n\n"
            f"النظام الآن في وضع <b>AUTO</b>.\n"
            f"الهجمات القادمة ستُعالَج تلقائياً.\n\n"
            f"⏰ {now_str}",
            reply_markup=markup)
        return {'toast': '▶️ AUTO enabled'}

    # ─── Attack-specific actions ───
    if attack is None:
        return {'toast': '❌ Attack not found'}

    src_ip = attack.get('src_ip')
    target_id = attack.get('target_id', '—')

    # 🛡️ DEFEND — combined block + honeypot for Critical, simple block otherwise
    if action == 'defend':
        if src_ip:
            st.session_state.blocked_ips.add(src_ip)
            if attack.get('severity') == 'Critical':
                st.session_state.honeypot_ips.add(src_ip)
                action_text = '🛡️ Defended (Block + Honeypot)'
            else:
                action_text = '🛡️ Defended (Blocked)'
        else:
            action_text = '🛡️ Defended'

        attack['action_taken'] = f'{action_text} (via Telegram)'
        attack['status'] = 'Resolved'
        attack['blocked_ip'] = src_ip
        attack['undone'] = False
        # Remove from pending alerts (no longer waiting for response)
        st.session_state.tg_pending_alerts.pop(str(attack['tg_index']), None)
        clear_attack_session(attack)  # 🔑 FIX
        # Remove from in-app pending decisions if present
        if attack in st.session_state.pending_decisions:
            st.session_state.pending_decisions.remove(attack)
            st.session_state.total_blocked += 1

        markup = build_inline_keyboard([
            [("↩️ تراجع", f"undo:{attack['tg_index']}")],
        ])
        telegram_send_message(token, chat_id,
            f"✅ <b>Action: 🛡️ Defended</b>\n\n"
            f"📍 IP: <code>{src_ip}</code> blocked\n"
            f"🎯 Target: {target_id}\n"
            f"🛡️ {action_text}\n"
            f"⏰ At: {now_str}\n\n"
            f"🛡️ Threat neutralized",
            reply_markup=markup)
        return {'toast': '🛡️ Defended'}

    # ✅ PASS — treat as false alarm, allow traffic
    if action == 'pass':
        if src_ip:
            st.session_state.blocked_ips.discard(src_ip)
            st.session_state.honeypot_ips.discard(src_ip)
        attack['action_taken'] = '✅ Passed (False Alarm) - via Telegram'
        attack['status'] = 'Resolved'
        attack['undone'] = False
        st.session_state.tg_pending_alerts.pop(str(attack['tg_index']), None)
        clear_attack_session(attack)  # 🔑 FIX
        if attack in st.session_state.pending_decisions:
            st.session_state.pending_decisions.remove(attack)

        markup = build_inline_keyboard([
            [("🛡️ تصدّي بدلاً", f"defend:{attack['tg_index']}")],
        ])
        telegram_send_message(token, chat_id,
            f"✅ <b>Action: Passed (False Alarm)</b>\n\n"
            f"📍 IP: <code>{src_ip}</code> permitted\n"
            f"🎯 Target: {target_id}\n"
            f"⏰ At: {now_str}\n\n"
            f"🟡 Traffic is now flowing — monitor carefully",
            reply_markup=markup)
        return {'toast': '✅ Passed'}

    # ↩️ UNDO — reverse previous action
    if action == 'undo':
        if src_ip:
            st.session_state.blocked_ips.discard(src_ip)
            st.session_state.honeypot_ips.discard(src_ip)
        prev = attack.get('action_taken', '')
        attack['action_taken'] = f'↩️ Undone (was: {prev})'
        attack['undone'] = True
        markup = build_inline_keyboard([
            [("🛡️ تصدّي مجدداً", f"defend:{attack['tg_index']}")],
        ])
        telegram_send_message(token, chat_id,
            f"↩️ <b>Action Reversed</b>\n\n"
            f"📍 IP: <code>{src_ip}</code> restored\n"
            f"🎯 Target: {target_id}\n"
            f"⏰ At: {now_str}\n\n"
            f"🟡 <b>Warning:</b> attack may resume.",
            reply_markup=markup)
        return {'toast': '↩️ Undone'}

    # ─── Legacy actions (still supported) ───
    if action == 'block':
        if src_ip:
            st.session_state.blocked_ips.add(src_ip)
        attack['action_taken'] = '🚫 Blocked (via Telegram)'
        attack['status'] = 'Resolved'
        attack['blocked_ip'] = src_ip
        attack['undone'] = False
        st.session_state.tg_pending_alerts.pop(str(attack['tg_index']), None)
        clear_attack_session(attack)  # 🔑 FIX
        markup = build_inline_keyboard([
            [("↩️ تراجع", f"undo:{attack['tg_index']}")],
        ])
        telegram_send_message(token, chat_id,
            f"✅ <b>Action: 🚫 Block</b>\n\n📍 {src_ip}\n⏰ {now_str}",
            reply_markup=markup)
        return {'toast': '🚫 Blocked'}

    if action == 'honeypot':
        if src_ip:
            st.session_state.blocked_ips.add(src_ip)
            st.session_state.honeypot_ips.add(src_ip)
        attack['action_taken'] = '🍯 Honeypot (via Telegram)'
        attack['status'] = 'Resolved'
        attack['undone'] = False
        st.session_state.tg_pending_alerts.pop(str(attack['tg_index']), None)
        clear_attack_session(attack)  # 🔑 FIX
        markup = build_inline_keyboard([
            [("↩️ تراجع", f"undo:{attack['tg_index']}")],
        ])
        telegram_send_message(token, chat_id,
            f"🍯 <b>Honeypot</b>\n📍 {src_ip}\n⏰ {now_str}",
            reply_markup=markup)
        return {'toast': '🍯 Honeypot'}

    if action == 'allow':
        if src_ip:
            st.session_state.blocked_ips.discard(src_ip)
        attack['action_taken'] = '✅ Allowed (via Telegram)'
        attack['status'] = 'Resolved'
        attack['undone'] = False
        st.session_state.tg_pending_alerts.pop(str(attack['tg_index']), None)
        clear_attack_session(attack)  # 🔑 FIX
        telegram_send_message(token, chat_id,
            f"✅ <b>Allow</b>\n📍 {src_ip}\n⏰ {now_str}")
        return {'toast': '✅ Allowed'}

    if action == 'handle_auto':
        attack = handle_attack_auto(attack)
        attack['action_taken'] += ' (via Telegram)'
        st.session_state.tg_pending_alerts.pop(str(attack['tg_index']), None)
        clear_attack_session(attack)  # 🔑 FIX
        markup = build_inline_keyboard([
            [("↩️ تراجع", f"undo:{attack['tg_index']}")],
        ])
        telegram_send_message(token, chat_id,
            f"🤖 <b>Auto Handled</b>\n✅ {attack['action_taken']}\n⏰ {now_str}",
            reply_markup=markup)
        return {'toast': '🤖 Auto-handled'}

    return {'toast': '❓ Unknown action'}


def check_telegram_timeouts():
    """🆕 Check pending Telegram alerts for 7-second timeout.

    BEHAVIOR (revised per user request):
      For any pending alert older than 7 seconds:
        1. Auto-handle the attack
        2. **GLOBALLY ACTIVATE AUTO MODE** + persistent banner
        3. Send 'timeout' notification with confirmation
    """
    if not st.session_state.tg_enabled:
        return 0
    token = st.session_state.tg_token.strip()
    chat_id = st.session_state.tg_chat_id.strip()
    if not token or not chat_id:
        return 0

    now = time.time()
    expired_keys = [
        k for k, v in st.session_state.tg_pending_alerts.items()
        if now > v.get('deadline', 0)
    ]

    if not expired_keys:
        return 0

    handled_count = 0
    last_handled = None   # 🆕 Tracks the most recent attack for post-defense view
    for k in expired_keys:
        pending = st.session_state.tg_pending_alerts.pop(k)
        attack = pending['attack']
        attack = handle_attack_auto(attack)
        attack['action_taken'] = f"⏰ Auto: {attack.get('action_taken','Handled')}"
        attack['undone'] = False
        if attack in st.session_state.pending_decisions:
            st.session_state.pending_decisions.remove(attack)
        clear_attack_session(attack)  # 🔑 FIX
        send_telegram_alert(attack, phase='timeout')
        st.session_state.tg_actions_log.append({
            'time': datetime.now().strftime('%H:%M:%S'),
            'action': 'timeout_auto',
            'attack': attack['name'],
            'result': '⏰ Auto-handled + AUTO activated'
        })
        last_handled = attack    # 🆕
        handled_count += 1

    # 🔥 Activate AUTO globally (persistent)
    trigger_auto_activation(handled_count, reason='7-second timeout (Telegram)')

    # 🆕 Stop the alarm 2 s after Telegram-timeout-triggered AUTO so
    # that the audio dies at T+9s from attack start (7s timeout + 2s
    # trail) — same contract as every other MANUAL auto-handle path.
    # Without this, when Telegram was enabled, check_telegram_timeouts
    # would fire BEFORE the in-place decision-phase timeout (since it
    # runs higher up in the page render order), clear_attack_session
    # would set show_simulation=False, the in-place timeout code would
    # be skipped, and the alarm's own stop_alarm_delayed call inside
    # that skipped block would never run — letting the audio play
    # until its internal 10s setTimeout.
    stop_alarm_delayed(2)

    # 🆕 Hold the post-defense view for 30 s so the operator sees the
    # neutralized 3D snapshot — same as the other AUTO-handle paths.
    # This is ALSO what schedules the 1-second autorefresh that gives
    # the alarm renderer the chance to detect expires_at and remove
    # the audio element exactly at T+9s.
    if last_handled is not None:
        start_post_defense_view(last_handled, mode='auto')

    return handled_count





