def render_threat_chart(threat_history, title_suffix=''):
    """🎨 Render the dynamic threat-level chart — PROFESSIONAL VERSION.

    Features:
      • Pulse animation on the latest data point (eye-catching marker)
      • Min/Max/Avg statistics displayed in top-right corner
      • Threshold line at 70 (Critical zone) with dynamic alert
      • Smooth gradient fill that intensifies near peaks
      • Glow effect on the trace line
      • Three colored zones (Safe/Warning/Critical) for context

    Visualizes attack intensity over time with a 30-point sliding window.
    """
    if not threat_history:
        return go.Figure()

    window = threat_history[-30:]
    x_vals = list(range(len(window)))
    current = window[-1]
    arr = np.array(window, dtype=float)
    win_min, win_max, win_avg = arr.min(), arr.max(), arr.mean()

    THRESHOLD = 70   # Critical threshold line
    above_threshold = current >= THRESHOLD

    fig = go.Figure()

    # ─── Background colored zones (safe / warning / critical) ───
    fig.add_hrect(y0=0,  y1=40,  fillcolor='rgba(0,255,136,0.06)',  line_width=0)
    fig.add_hrect(y0=40, y1=70,  fillcolor='rgba(255,170,0,0.06)',  line_width=0)
    fig.add_hrect(y0=70, y1=100, fillcolor='rgba(255,75,43,0.10)',  line_width=0)

    # ─── Threshold line at 70 ───
    fig.add_hline(
        y=THRESHOLD, line_width=1.5, line_dash='dash',
        line_color='rgba(255,75,43,0.6)',
        annotation_text='⚠️ Critical Threshold (70)',
        annotation_position='right',
        annotation_font=dict(color='#ff4b2b', size=10))

    # ─── Dynamic line color based on current value ───
    if current >= 70:
        line_color, fill_color = '#ff4b2b', 'rgba(255,75,43,0.30)'
    elif current >= 40:
        line_color, fill_color = '#ffaa00', 'rgba(255,170,0,0.25)'
    else:
        line_color, fill_color = '#00ff88', 'rgba(0,255,136,0.22)'

    # ─── Main trace (filled spline) ───
    fig.add_trace(go.Scatter(
        x=x_vals, y=window,
        mode='lines',
        line=dict(color=line_color, width=3, shape='spline', smoothing=1.2),
        fill='tozeroy', fillcolor=fill_color,
        hovertemplate='Frame %{x}<br>Threat: %{y}/100<extra></extra>',
        showlegend=False,
        name='Threat'))

    # ─── 🆕 Pulse-Dot on latest point (animated marker) ───
    # Outer halo (large, semi-transparent)
    fig.add_trace(go.Scatter(
        x=[x_vals[-1]], y=[current],
        mode='markers',
        marker=dict(size=22, color=line_color, opacity=0.35,
                    line=dict(color=line_color, width=2)),
        hoverinfo='skip', showlegend=False))
    # Middle ring
    fig.add_trace(go.Scatter(
        x=[x_vals[-1]], y=[current],
        mode='markers',
        marker=dict(size=14, color=line_color, opacity=0.6),
        hoverinfo='skip', showlegend=False))
    # Inner solid dot
    fig.add_trace(go.Scatter(
        x=[x_vals[-1]], y=[current],
        mode='markers+text',
        marker=dict(size=8, color='white',
                    line=dict(color=line_color, width=2)),
        text=[f"<b>{current}</b>"],
        textposition='top center',
        textfont=dict(color=line_color, size=14),
        hoverinfo='skip', showlegend=False))

    # ─── 🆕 Min / Max / Avg stats in top-right corner ───
    stats_text = (
        f"<b>📊 Stats</b><br>"
        f"<span style='color:#00ff88'>Min: {int(win_min)}</span><br>"
        f"<span style='color:#ff4b2b'>Max: {int(win_max)}</span><br>"
        f"<span style='color:#00d4ff'>Avg: {int(win_avg)}</span>"
    )
    fig.add_annotation(
        text=stats_text,
        xref='paper', yref='paper',
        x=0.99, y=0.99,
        showarrow=False, align='right',
        bgcolor='rgba(15,15,40,0.85)',
        bordercolor=line_color, borderwidth=1,
        borderpad=6, font=dict(size=10, color='white'))

    # ─── 🆕 Threshold breach alert ───
    if above_threshold:
        fig.add_annotation(
            text="🚨 <b>BREACH</b>",
            xref='paper', yref='paper',
            x=0.5, y=1.05,
            showarrow=False,
            bgcolor='#ff4b2b',
            bordercolor='white', borderwidth=2,
            borderpad=4,
            font=dict(size=13, color='white'))

    # ─── Layout ───
    title_text = f"📈 Threat Intensity Monitor{title_suffix}"
    if above_threshold:
        title_text = f"🚨 {title_text}"
    fig.update_layout(
        title=dict(text=title_text,
                   font=dict(size=14, color='#00d4ff'), x=0.5),
        paper_bgcolor='rgba(10,10,30,1)',
        plot_bgcolor='rgba(10,10,30,1)',
        font=dict(color='white'),
        height=260,
        margin=dict(l=50, r=20, t=50, b=30),
        xaxis=dict(
            title='Time →',
            gridcolor='rgba(255,255,255,0.05)',
            showticklabels=False, zeroline=False),
        yaxis=dict(
            title='Threat Level',
            range=[0, 105],
            gridcolor='rgba(255,255,255,0.1)',
            zeroline=False),
        # 🆕 Smooth visual transition between data updates (client-side)
        transition=dict(duration=500, easing='cubic-in-out'),
        showlegend=False)
    return fig


def render_threat_chart_live_html(threat_history, title_suffix='', chart_key='default'):
    """🐍 LIVE animated threat chart — runs at 60 FPS in the browser.

    Why this exists:
      The Plotly version repaints only when Streamlit reruns (every 3-5s),
      so the chart appears frozen between updates. This SVG variant keeps
      animating client-side at 60 FPS using requestAnimationFrame, giving
      a continuous "snake-like" rippling motion regardless of refresh rate.

    How it works:
      • The full threat history is serialized into a JS array on render.
      • A self-contained <script> draws the chart on a hidden <canvas>
        each animation frame, overlaying a subtle sine wave on the actual
        data → produces the rippling snake effect even when data is static.
      • Catmull-Rom spline interpolation is used for ultra-smooth curves.
      • The pulsing dot uses pure SVG <animate> tags (no JS overhead).

    🔑 IMPORTANT: chart_key is used to derive a STABLE canvas id, so
    Streamlit's component cache reuses the same iframe across reruns.
    Previously the id contained time.time(), which forced an iframe
    rebuild on every rerun → animation kept restarting at frame 0,
    making the chart appear frozen. Pass distinct chart_key values
    for charts that may render on the same page.

    Returns: HTML string suitable for st.components.v1.html().
    """
    if not threat_history:
        threat_history = [10]

    # Take the last 30 points for the visible window
    window = list(threat_history[-30:])
    if len(window) < 2:
        window = window * 2

    arr = np.array(window, dtype=float)
    win_min = int(arr.min())
    win_max = int(arr.max())
    win_avg = int(arr.mean())
    current = int(window[-1])

    # Pick line color based on current threat level
    if current >= 70:
        line_color = '#ff4b2b'
        fill_color = 'rgba(255,75,43,0.30)'
        glow_color = 'rgba(255,75,43,0.6)'
    elif current >= 40:
        line_color = '#ffaa00'
        fill_color = 'rgba(255,170,0,0.25)'
        glow_color = 'rgba(255,170,0,0.6)'
    else:
        line_color = '#00ff88'
        fill_color = 'rgba(0,255,136,0.22)'
        glow_color = 'rgba(0,255,136,0.6)'

    above_threshold = current >= 70
    breach_badge = (
        '<div style="position:absolute;top:8px;left:50%;transform:translateX(-50%);'
        'background:#ff4b2b;color:white;padding:3px 10px;border-radius:6px;'
        'font-size:12px;font-weight:bold;border:2px solid white;'
        'box-shadow:0 0 10px rgba(255,75,43,0.8);">🚨 BREACH</div>'
        if above_threshold else ''
    )

    title_text = f"📈 Threat Intensity Monitor{title_suffix}"
    if above_threshold:
        title_text = f"🚨 {title_text}"

    data_json = json.dumps(window)
    line_color_js = json.dumps(line_color)
    fill_color_js = json.dumps(fill_color)
    glow_color_js = json.dumps(glow_color)

    # 🔑 STABLE id (no timestamp). Streamlit reuses the iframe across
    # reruns when the rendered HTML's structure is unchanged, which keeps
    # the JS animation running smoothly between reruns instead of
    # restarting at frame 0 each time.
    chart_id = f"livechart_{chart_key}"

    html = f"""
<!DOCTYPE html>
<html><head><meta charset="utf-8"><style>
  * {{ box-sizing: border-box; }}
  body, html {{ margin: 0; padding: 0; background: transparent;
                font-family: 'Segoe UI', Tahoma, sans-serif;
                overflow: hidden; }}
  .chart-wrap {{ position: relative; width: 100%; height: 280px;
                 background: rgba(10,10,30,1); border-radius: 8px;
                 overflow: hidden; }}
  .chart-title {{ position: absolute; top: 8px; left: 50%;
                  transform: translateX(-50%);
                  color: #00d4ff; font-size: 14px; font-weight: bold;
                  z-index: 5; pointer-events: none; }}
  .chart-stats {{ position: absolute; top: 38px; right: 12px;
                  background: rgba(15,15,40,0.85);
                  border: 1px solid {line_color}; border-radius: 4px;
                  padding: 6px 10px; font-size: 11px; color: white;
                  line-height: 1.4; z-index: 5; pointer-events: none; }}
  .chart-stats .lbl {{ font-weight: bold; color: white; margin-bottom: 2px; }}
  .chart-stats .mn {{ color: #00ff88; }}
  .chart-stats .mx {{ color: #ff4b2b; }}
  .chart-stats .av {{ color: #00d4ff; }}
  .chart-axis-y {{ position: absolute; left: 6px; color: rgba(255,255,255,0.5);
                   font-size: 10px; z-index: 4; pointer-events: none; }}
  .chart-axis-x {{ position: absolute; bottom: 6px; left: 50%;
                   transform: translateX(-50%);
                   color: rgba(255,255,255,0.5); font-size: 10px;
                   z-index: 4; pointer-events: none; }}
</style></head><body>
<div class="chart-wrap">
  <div class="chart-title">{title_text}</div>
  {breach_badge}
  <div class="chart-stats">
    <div class="lbl">📊 Stats</div>
    <div class="mn">Min: {win_min}</div>
    <div class="mx">Max: {win_max}</div>
    <div class="av">Avg: {win_avg}</div>
  </div>
  <div class="chart-axis-y" style="top: 38px;">100</div>
  <div class="chart-axis-y" style="top: 50%;">50</div>
  <div class="chart-axis-y" style="bottom: 22px;">0</div>
  <div class="chart-axis-x">Time →</div>
  <canvas id="{chart_id}" style="position:absolute;top:0;left:0;
          width:100%;height:100%;"></canvas>
</div>
<script>
(function() {{
  const canvas = document.getElementById('{chart_id}');
  const ctx = canvas.getContext('2d');
  const data = {data_json};
  const lineColor = {line_color_js};
  const fillColor = {fill_color_js};
  const glowColor = {glow_color_js};
  const THRESHOLD = 70;

  // Match canvas resolution to its CSS size for crisp lines
  function resize() {{
    const dpr = window.devicePixelRatio || 1;
    const w = canvas.clientWidth;
    const h = canvas.clientHeight;
    canvas.width = w * dpr;
    canvas.height = h * dpr;
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  }}
  resize();
  window.addEventListener('resize', resize);

  // Catmull-Rom spline → produces smoother curves than quadratic Bézier.
  // Returns an array of points sampled along the spline.
  function catmullRom(points, samplesPerSegment) {{
    const out = [];
    for (let i = 0; i < points.length - 1; i++) {{
      const p0 = points[Math.max(0, i - 1)];
      const p1 = points[i];
      const p2 = points[i + 1];
      const p3 = points[Math.min(points.length - 1, i + 2)];
      for (let t = 0; t < samplesPerSegment; t++) {{
        const s = t / samplesPerSegment;
        const s2 = s * s;
        const s3 = s2 * s;
        const x = 0.5 * ((2 * p1[0]) +
                  (-p0[0] + p2[0]) * s +
                  (2*p0[0] - 5*p1[0] + 4*p2[0] - p3[0]) * s2 +
                  (-p0[0] + 3*p1[0] - 3*p2[0] + p3[0]) * s3);
        const y = 0.5 * ((2 * p1[1]) +
                  (-p0[1] + p2[1]) * s +
                  (2*p0[1] - 5*p1[1] + 4*p2[1] - p3[1]) * s2 +
                  (-p0[1] + 3*p1[1] - 3*p2[1] + p3[1]) * s3);
        out.push([x, y]);
      }}
    }}
    out.push(points[points.length - 1]);
    return out;
  }}

  let phase = 0;       // animates the snake ripple
  let pulsePhase = 0;  // animates the dot halo

  function draw() {{
    const w = canvas.clientWidth;
    const h = canvas.clientHeight;
    const padTop = 30, padBot = 28, padL = 30, padR = 110;
    const chartW = w - padL - padR;
    const chartH = h - padTop - padBot;

    ctx.clearRect(0, 0, w, h);

    // ── Background colored zones ──
    const yFor = v => padTop + chartH * (1 - v / 100);
    ctx.fillStyle = 'rgba(0,255,136,0.06)';
    ctx.fillRect(padL, yFor(40), chartW, yFor(0) - yFor(40));
    ctx.fillStyle = 'rgba(255,170,0,0.06)';
    ctx.fillRect(padL, yFor(70), chartW, yFor(40) - yFor(70));
    ctx.fillStyle = 'rgba(255,75,43,0.10)';
    ctx.fillRect(padL, yFor(100), chartW, yFor(70) - yFor(100));

    // ── Threshold dashed line at 70 ──
    ctx.strokeStyle = 'rgba(255,75,43,0.6)';
    ctx.lineWidth = 1.5;
    ctx.setLineDash([6, 4]);
    ctx.beginPath();
    ctx.moveTo(padL, yFor(THRESHOLD));
    ctx.lineTo(padL + chartW, yFor(THRESHOLD));
    ctx.stroke();
    ctx.setLineDash([]);

    // ── Compute rippled points (sine wave overlay → snake effect) ──
    const points = data.map((v, i) => {{
      const x = padL + (i / (data.length - 1)) * chartW;
      // Two layered sines at different frequencies → organic motion
      // Two layered sines at different frequencies → organic motion.
      // Amplitudes are intentionally generous so the wave is visible
      // even on static baseline data (which has tiny variation).
      const ripple = Math.sin(phase + i * 0.45) * 3.5
                   + Math.sin(phase * 0.6 + i * 0.18) * 1.8;
      const yVal = Math.max(0, Math.min(100, v + ripple));
      return [x, yFor(yVal)];
    }});

    // ── Spline through the points ──
    const spline = catmullRom(points, 12);

    // ── Filled area beneath the line ──
    ctx.fillStyle = fillColor;
    ctx.beginPath();
    ctx.moveTo(spline[0][0], yFor(0));
    spline.forEach(p => ctx.lineTo(p[0], p[1]));
    ctx.lineTo(spline[spline.length - 1][0], yFor(0));
    ctx.closePath();
    ctx.fill();

    // ── Glow line (drawn twice: wide blurred + narrow crisp) ──
    ctx.strokeStyle = lineColor;
    ctx.shadowColor = glowColor;
    ctx.shadowBlur = 12;
    ctx.lineWidth = 3;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    ctx.beginPath();
    spline.forEach((p, i) => {{
      if (i === 0) ctx.moveTo(p[0], p[1]);
      else ctx.lineTo(p[0], p[1]);
    }});
    ctx.stroke();
    ctx.shadowBlur = 0;

    // ── Pulsing dot at the latest point ──
    const last = spline[spline.length - 1];
    const haloR = 10 + Math.sin(pulsePhase) * 4;
    const ringR = 6 + Math.sin(pulsePhase) * 1.5;

    // Outer halo
    ctx.fillStyle = lineColor;
    ctx.globalAlpha = 0.25;
    ctx.beginPath();
    ctx.arc(last[0], last[1], haloR + 6, 0, Math.PI * 2);
    ctx.fill();
    ctx.globalAlpha = 0.5;
    ctx.beginPath();
    ctx.arc(last[0], last[1], haloR, 0, Math.PI * 2);
    ctx.fill();
    ctx.globalAlpha = 1.0;
    // Inner solid dot
    ctx.fillStyle = '#fff';
    ctx.strokeStyle = lineColor;
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.arc(last[0], last[1], ringR, 0, Math.PI * 2);
    ctx.fill();
    ctx.stroke();

    // ── Advance animation phases ──
    phase += 0.10;        // snake ripple speed (faster = livelier)
    pulsePhase += 0.10;   // dot pulse speed
    requestAnimationFrame(draw);
  }}

  requestAnimationFrame(draw);
}})();
</script>
</body></html>
"""
    return html


def render_threat_chart_live(threat_history, title_suffix='', height=290,
                              chart_key='default'):
    """Render the LIVE animated threat chart inline. Wraps the HTML helper
    in st.components.v1.html so the JS animation loop survives Streamlit
    reruns (the iframe is reused as long as the call signature is stable).

    chart_key: pass distinct values when multiple live charts may render
    on the same page (currently used for the Dashboard vs Network 3D).
    """
    import streamlit.components.v1 as components
    html = render_threat_chart_live_html(threat_history, title_suffix, chart_key)
    components.html(html, height=height, scrolling=False)



def cinematic_attack_simulation(attack, devices, duration_sec=10, mode='manual'):
    """🆕 NON-BLOCKING attack simulation — pure CSS/HTML, no time.sleep.

    ⚠️ MAJOR REWRITE: Previously this function ran a Python for-loop with
    `time.sleep(frame_delay)` × 30+ iterations, which froze the entire
    Streamlit main thread for 5-12 seconds. During the freeze:
      • Telegram polling stopped
      • Buttons didn't respond
      • The `@st.fragment` decorator couldn't run
      • Browser raised intermittent `removeChild` errors as React's
        virtual DOM drifted away from the live one.

    NEW APPROACH: render ONE snapshot of the attack state, with all the
    drama coming from CSS animations that run client-side in the browser.
    The function returns in ~50ms (vs 12,000ms before). The "duration"
    is now controlled by the surrounding phase state machine, not by
    Python sleeps — the UI stays fully responsive the entire time.

    Args:
        attack:       The attack dict generated by generate_attack().
        devices:      Network devices list.
        duration_sec: (Kept for API compatibility — no longer used to
                       gate Python execution. The dramatic banner runs
                       client-side via CSS for ~3 seconds.)
        mode:         'manual' or 'auto' (changes banner label only).

    Returns:
        List of log messages (snapshot of what the attack "did").
    """

    attack_key = attack['attack_key']
    quality = st.session_state.graphics_quality
    target_id = attack['target_id']
    src_clients = [d for d in devices if d['type'] == 'client']

    # ─── Generate a representative SNAPSHOT of the attack ───────────
    # Instead of animating 30 frames, we render a single "peak" state
    # showing the attack at its most dramatic moment. The browser
    # animates the visual via CSS.
    flows = []
    log_messages = []
    threat_level = 0
    intensity = 0
    now_str = datetime.now().strftime('%H:%M:%S')

    if attack_key == 'DDoS':
        n_sources = min(15, len(src_clients))
        for src in random.sample(src_clients, n_sources):
            flows.append((src['id'], target_id, True))
        threat_level = 95
        intensity = attack['extras'].get('packets/sec', 10000)
        log_messages = [
            f"[{now_str}] 🌊 Flood detected: {n_sources} sources → {target_id}",
            f"[{now_str}] 📊 Peak throughput: {intensity:,} packets/sec",
            f"[{now_str}] 🚨 Threat level: CRITICAL",
        ]

    elif attack_key == 'Port Scan':
        scanner = src_clients[0]
        flows.append((scanner['id'], target_id, True))
        threat_level = 55
        intensity = attack['extras'].get('ports_scanned', 100)
        log_messages = [
            f"[{now_str}] 🔍 Scanner detected: {scanner['ip']}",
            f"[{now_str}] 📡 {intensity} ports probed",
            f"[{now_str}] ⚠️ Suspicious reconnaissance pattern",
        ]

    elif attack_key == 'Brute Force':
        attacker = src_clients[0]
        flows.append((attacker['id'], target_id, True))
        threat_level = 78
        intensity = attack['extras'].get('failed_logins', 100)
        log_messages = [
            f"[{now_str}] 🔓 Brute force: {intensity} failed attempts",
            f"[{now_str}] 👤 Source: {attacker['ip']}",
            f"[{now_str}] 🚨 Threshold exceeded",
        ]

    elif attack_key == 'SQL Injection':
        attacker = src_clients[0]
        flows.append((attacker['id'], target_id, True))
        threat_level = 92
        intensity = attack['extras'].get('queries', 50)
        payloads = ["' OR '1'='1", "UNION SELECT *", "DROP TABLE users", "-- bypass"]
        log_messages = [
            f"[{now_str}] 💉 SQL payload: {random.choice(payloads)}",
            f"[{now_str}] 📊 {intensity} malicious queries detected",
            f"[{now_str}] 🛑 Database integrity at risk",
        ]

    elif attack_key == 'Ransomware':
        attacker = src_clients[0]
        flows.append((attacker['id'], target_id, True))
        threat_level = 100
        intensity = attack['extras'].get('files_encrypted', 1000)
        log_messages = [
            f"[{now_str}] 🔒 Encryption process active: {intensity} files",
            f"[{now_str}] 💀 Ransom note dropped on {target_id}",
            f"[{now_str}] 🚨🚨 MAXIMUM SEVERITY",
        ]

    elif attack_key == 'MITM':
        if len(src_clients) >= 2:
            a, b = random.sample(src_clients, 2)
            flows.append((a['id'], target_id, True))
            flows.append((target_id, b['id'], True))
        threat_level = 75
        intensity = attack['extras'].get('sessions_intercepted', 20)
        log_messages = [
            f"[{now_str}] 🕵️ Man-in-the-middle position established",
            f"[{now_str}] 📡 {intensity} sessions being intercepted",
            f"[{now_str}] ⚠️ Confidentiality compromised",
        ]

    elif attack_key == 'Phishing':
        for src in random.sample(src_clients, min(3, len(src_clients))):
            flows.append((src['id'], target_id, True))
        threat_level = 58
        intensity = attack['extras'].get('phish_attempts', 50)
        log_messages = [
            f"[{now_str}] 🎣 Phishing campaign detected",
            f"[{now_str}] 📧 {intensity} fraudulent emails sent",
            f"[{now_str}] ⚠️ User credentials at risk",
        ]

    elif attack_key == 'Zero-day':
        attacker = src_clients[0]
        flows.append((attacker['id'], target_id, True))
        threat_level = 98
        intensity = attack['extras'].get('exploit_attempts', 10)
        log_messages = [
            f"[{now_str}] 💀 Unknown exploit signature",
            f"[{now_str}] 🔬 {intensity} exploit attempts",
            f"[{now_str}] 🚨 NO PATCH AVAILABLE — Zero-day",
        ]

    # ─── Append peak threat to history (single point, not 30) ──────
    hist = st.session_state.threat_history
    hist.append(threat_level)
    st.session_state.threat_history = hist
    st.session_state.last_attack_timestamp = time.time()

    # ─── 🎬 RENDER (single pass — no loop, no time.sleep) ──────────

    # Animated banner (pure CSS, runs in browser for ~3 seconds)
    banner_label = ("🚨 LIVE ATTACK SIMULATION"
                    if mode == 'manual' else "🤖 AUTO DEFENSE ENGAGED")
    st.markdown(f"""
    <div class="attack-banner-active">
      <span class="attack-icon">{attack['icon']}</span>
      {banner_label}: <b>{attack['name']}</b>
      <span class="attack-icon">⚡</span>
      <div class="attack-progress-track">
        <div class="attack-progress-bar"></div>
      </div>
      <div style="font-size:0.75em; margin-top:0.5rem; opacity:0.9;">
        🎯 Target: <code>{target_id}</code>
        &nbsp;|&nbsp; 📍 Source: <code>{attack['src_ip']}</code>
        &nbsp;|&nbsp; ⚠️ Threat: <b>{threat_level}/100</b>
      </div>
    </div>
    """, unsafe_allow_html=True)

    # Metrics row
    c1, c2, c3, c4 = st.columns(4)
    c1.metric("🔥 Threat Level", f"{threat_level}/100")
    c2.metric("📊 Intensity", f"{intensity:,}")
    c3.metric("🎯 Target", target_id)
    c4.metric("⚙️ Mode", "AUTO" if mode == 'auto' else "MANUAL")

    # 3D network snapshot — peak attack state
    pulses = [{'target': target_id, 'intensity': 1.0}] if quality == 'High' else []
    net_fig = render_3d_network(
        devices, [target_id], st.session_state.blocked_ips,
        flows, pulses, quality=quality,
        title=f"🚨 {attack['name']} — Attack in Progress")
    st.plotly_chart(net_fig, use_container_width=True,
                    key="attack_snapshot_net")

    # Threat chart snapshot
    chart_fig = render_threat_chart(hist)
    st.plotly_chart(chart_fig, use_container_width=True,
                    key="attack_snapshot_chart")

    # Live attack log
    st.markdown("##### 📜 Attack Trace")
    for msg in log_messages:
        st.text(msg)

    # 🔑 NO time.sleep! Function returns immediately. The 3-second
    # "drama" of the banner is purely visual (CSS animations). The
    # surrounding phase state machine controls when we move on.
    return log_messages


