# ML Models
# =====================================================================
@st.cache_resource
def train_models():
    np.random.seed(42)
    n_n, n_a = 3500, 1500
    normal = pd.DataFrame({
        'duration':      np.random.exponential(2, n_n),
        'src_bytes':     np.random.normal(500, 150, n_n).clip(0),
        'dst_bytes':     np.random.normal(800, 200, n_n).clip(0),
        'packet_count':  np.random.poisson(20, n_n),
        'failed_logins': np.random.poisson(0.1, n_n),
        'connections':   np.random.poisson(5, n_n),
        'error_rate':    np.random.beta(1, 20, n_n),
        'label': 0
    })
    attack = pd.DataFrame({
        'duration':      np.random.exponential(0.5, n_a),
        'src_bytes':     np.random.normal(2000, 500, n_a).clip(0),
        'dst_bytes':     np.random.normal(100, 50, n_a).clip(0),
        'packet_count':  np.random.poisson(150, n_a),
        'failed_logins': np.random.poisson(3, n_a),
        'connections':   np.random.poisson(50, n_a),
        'error_rate':    np.random.beta(5, 2, n_a),
        'label': 1
    })
    df = pd.concat([normal, attack], ignore_index=True).sample(frac=1, random_state=42)
    feats = [c for c in df.columns if c != 'label']
    X, y = df[feats], df['label']
    Xtr, Xte, ytr, yte = train_test_split(X, y, test_size=0.3,
                                          random_state=42, stratify=y)
    sc = StandardScaler().fit(Xtr)
    rf = RandomForestClassifier(n_estimators=100, random_state=42, n_jobs=-1)
    rf.fit(sc.transform(Xtr), ytr)
    iso = IsolationForest(contamination=0.3, random_state=42)
    iso.fit(sc.transform(Xtr)[ytr == 0])
    return {
        'rf': rf, 'iso': iso, 'scaler': sc, 'features': feats,
        'X_test': Xte, 'X_test_s': sc.transform(Xte),
        'y_test': yte, 'df': df
    }


