# 🆕 Telegram Interactive Bot — automatic polling via fragment
# ════════════════════════════════════════════════════════════════════
# DESIGN: We use Streamlit's @st.fragment(run_every="3s") for the
# polling logic. This means:
#   • The fragment alone re-runs every 3 seconds (not the whole page)
#   • The 3D network, charts, and other UI never flicker
#   • CPU/bandwidth load drops ~90% vs full-page autorefresh
#   • If we detect commands → trigger st.rerun() to update the rest of the page
#
# GRACEFUL FALLBACK: if @st.fragment is missing (Streamlit < 1.33),
# we fall back to a simple rendering and rely on existing autorefresh
# triggers (autorefresh-on-urgent + user interaction).
# ════════════════════════════════════════════════════════════════════

# Detect fragment support (Streamlit 1.33+)
_HAS_FRAGMENT = hasattr(st, 'fragment')


def _render_telegram_status_block():
    """Pure-rendering helper: shows the manual refresh button, pulsing
    LIVE indicator, last-poll countdown, and the recent actions log.
    Called from inside the auto-polling fragment AND from the fallback
    static path so the UI looks identical in both cases."""

    # ── Live status row (pulsing dot + manual button) ──────────────
    last_poll_ts = st.session_state.get('tg_last_poll_time', 0)
    secs_since = int(time.time() - last_poll_ts) if last_poll_ts else 999
    net_ok = st.session_state.get('_tg_net_cache', {}).get('ok', True)

    if net_ok:
        dot_color = '#00ff88'
        dot_label = 'LIVE'
    else:
        dot_color = '#ff4b2b'
        dot_label = 'OFFLINE'

    secs_text = (f"الآن" if secs_since < 2
                 else f"منذ {secs_since} ثانية" if secs_since < 60
                 else f"منذ {secs_since // 60} د")

    st.markdown(f"""
    <div style='display:flex; align-items:center; gap:8px;
                padding:6px 10px; background:rgba(0,0,0,0.25);
                border-radius:8px; margin-bottom:8px;
                font-size:0.85em;'>
      <span style='width:10px; height:10px; border-radius:50%;
                   background:{dot_color};
                   box-shadow:0 0 10px {dot_color};
                   animation:tg-pulse 1.5s ease-in-out infinite;'></span>
      <b style='color:{dot_color};'>🟢 {dot_label}</b>
      <span style='color:#888; margin-left:auto;'>
        التحديث {secs_text}
      </span>
    </div>
    <style>
      @keyframes tg-pulse {{
        0%, 100% {{ opacity: 1; transform: scale(1); }}
        50%      {{ opacity: 0.5; transform: scale(0.85); }}
      }}
    </style>
    """, unsafe_allow_html=True)

    st.caption("التحديث تلقائي كل 3 ثوان • أو اضغط للتحديث الفوري")
    if st.button("🔄 تحديث فوري الآن", use_container_width=True,
                 type="primary", key="tg_manual_refresh"):
        with st.spinner("جاري الاستلام..."):
            n = process_telegram_callbacks()
            st.session_state.tg_last_poll_time = time.time()
        if n > 0:
            st.success(f"✅ تم تنفيذ {n} أمر")
            st.rerun()
        else:
            st.info("📭 لا توجد أوامر جديدة")

    # ── Last action + history ──────────────────────────────────────
    log = st.session_state.get('tg_actions_log', [])
    if log:
        last = log[-1]
        st.markdown(
            f"<div style='font-size:0.85em; opacity:0.85;'>"
            f"<b>📱 آخر إجراء:</b><br>"
            f"<code>{last['time']}</code> — {last['result']}"
            f"</div>",
            unsafe_allow_html=True)
        with st.popover("📜 آخر 10 أوامر", use_container_width=True):
            for entry in log[-10:][::-1]:
                st.markdown(
                    f"`{entry['time']}` **{entry['result']}** — "
                    f"<i>{entry['attack']}</i>",
                    unsafe_allow_html=True)


if _HAS_FRAGMENT:
    @st.fragment(run_every="3s")
    def telegram_live_poll_fragment():
        """Re-runs every 3 seconds INDEPENDENTLY of the rest of the page.
        This is the core of the auto-refresh: the heavy poll happens here,
        and we trigger a full page rerun only when commands are actually
        received (so other UI sections update with the new state)."""
        # Run the actual poll (throttled internally by `should_poll`)
        last_poll = st.session_state.get('tg_last_poll_time', 0)
        if (time.time() - last_poll) > TELEGRAM_POLL_INTERVAL:
            st.session_state.tg_last_poll_time = time.time()
            try:
                actions_taken = process_telegram_callbacks()
            except Exception:
                actions_taken = 0
            if actions_taken > 0:
                # Real changes arrived → rerun the whole page so the
                # Dashboard / Network / etc reflect the new state.
                st.session_state['tg_action_notice'] = {
                    'time': time.time(),
                    'count': actions_taken,
                }
                st.toast(f"📱 تم استلام {actions_taken} أمر من Telegram",
                         icon="📲")
                st.rerun()
        # Always render the visible status block
        _render_telegram_status_block()


if st.session_state.tg_enabled:
    with st.sidebar.expander("📲 Telegram Commands", expanded=False):
        if _HAS_FRAGMENT:
            # Modern path: auto-polling fragment (re-runs every 3s)
            telegram_live_poll_fragment()
        else:
            # Fallback: render statically; polling happens during normal
            # page reruns (existing autorefresh / interactions).
            last_poll = st.session_state.get('tg_last_poll_time', 0)
            if (time.time() - last_poll) > TELEGRAM_POLL_INTERVAL:
                st.session_state.tg_last_poll_time = time.time()
                try:
                    actions_taken = process_telegram_callbacks()
                except Exception:
                    actions_taken = 0
                if actions_taken > 0:
                    st.session_state['tg_action_notice'] = {
                        'time': time.time(),
                        'count': actions_taken,
                    }
                    st.toast(f"📱 تم استلام {actions_taken} أمر من Telegram",
                             icon="📲")
            _render_telegram_status_block()

