# 🆕 Smart Auto-Refresh — only when truly needed (saves resources).
# Logic:
#   • Urgent (pending decisions / Telegram alerts) → 2s (snappy countdown)
#   • Active attack simulation → 2s (banner + decision phase ticks)
#   • Dynamic page (Dashboard chart) → 5s (lighter)
#   • Otherwise (static reports/history pages) → no refresh
#
# 🔑 BIG CHANGE: now that cinematic_attack_simulation no longer contains
# time.sleep, we MUST refresh during simulations — otherwise the 7-second
# decision deadline countdown stays frozen on screen until the user
# clicks something. The new banner has CSS animations that don't need
# Python reruns, but the deadline timer text does.
if HAS_AUTOREFRESH:
    has_urgent_pending = (
        len(st.session_state.pending_decisions) > 0
        or len(st.session_state.tg_pending_alerts) > 0
    )
    is_dynamic_page = page in [
        "🏠 Dashboard"
    ]
    is_simulating = st.session_state.get('show_simulation', False)

    if has_urgent_pending or is_simulating:
        # 2-second tick — drives the 7s decision countdown smoothly
        st_autorefresh(interval=2000, key="urgent_refresh")
    elif is_dynamic_page:
        # Lighter cadence for the dashboard chart animation
        st_autorefresh(interval=5000, key="dynamic_refresh")


